use axum::{extract::{Path, State}, response::IntoResponse, Json};
use uuid::Uuid;
use std::time::Duration;
use crate::application::dto::{DisbursementRequest, DisbursementResponse};
use crate::application::error::ApiError;
use crate::app_state::AppState;

pub struct LoanHandler;

impl LoanHandler {
    #[tracing::instrument(skip(state, req), fields(loan_id = %loan_id))]
    pub async fn disburse(
        State(state): State<AppState>,
        Path(loan_id): Path<Uuid>,
        Json(req): Json<DisbursementRequest>,
    ) -> Result<Json<DisbursementResponse>, ApiError> {
        let mut attempts = 0u32;
        loop {
            match state.ledger.disburse(loan_id, req.amount_cents).await {
                Ok(id) => return Ok(Json(DisbursementResponse { ledger_id: id })),
                Err(_) if attempts < state.config.disburse_max_retries => {
                    // BUG: std::thread::sleep inside an async fn — blocks the executor.
                    // On a money-critical path; gets auto-promoted to P1 via critical_paths.
                    std::thread::sleep(Duration::from_millis(state.config.disburse_backoff_ms));
                    attempts += 1;
                }
                Err(_) => return Err(ApiError::Dependency),
            }
        }
    }
}
